-- Import NE technician assessments from Microsoft Forms export
-- Source: NE Responses - TAB Skills Self-Assessment.xlsx
-- PREREQ: run supabase/assessments-rpcs.sql first — or use ne-assessments-complete.sql (all-in-one).
-- Safe to re-run.

-- Backfill technician_id from legacy tech_id column if present
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'assessments' AND column_name = 'tech_id'
  ) THEN
    UPDATE public.assessments
    SET technician_id = tech_id
    WHERE technician_id IS NULL AND tech_id IS NOT NULL;
  END IF;
END $$;

-- Drop duplicate rows so (technician_id, date) can be unique (keeps one row per pair)
DELETE FROM public.assessments a
WHERE a.technician_id IS NOT NULL
  AND a.ctid NOT IN (
    SELECT max(b.ctid)
    FROM public.assessments b
    WHERE b.technician_id IS NOT NULL
    GROUP BY b.technician_id, b.date
  );

CREATE UNIQUE INDEX IF NOT EXISTS assessments_technician_id_date_uidx
  ON public.assessments (technician_id, date);

DROP TABLE IF EXISTS public._ne_import_staging;
CREATE TABLE public._ne_import_staging (
  action text NOT NULL,
  tech_name text NOT NULL,
  assessment_date date,
  safety_avg numeric,
  basic_avg numeric,
  intermediate_avg numeric,
  advanced_avg numeric,
  survey_avg numeric,
  comment text,
  raw_scores jsonb
);

